import{_ as t,a,o,a6 as r}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse('{"title":"Interactive Playground Guide","description":"","frontmatter":{},"headers":[],"relativePath":"api/rest-api/playground.md","filePath":"api/rest-api/playground.md","lastUpdated":1787290888000}'),i={name:"api/rest-api/playground.md"};function n(s,e,d,h,l,c){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="interactive-playground-guide" tabindex="-1">Interactive Playground Guide <a class="header-anchor" href="#interactive-playground-guide" aria-label="Permalink to &quot;Interactive Playground Guide&quot;">​</a></h1><p>Bagisto ships <strong>Swagger UI</strong> for the REST API — every endpoint listed with its parameters, request body, and response schema, and a <strong>Try it out</strong> button that fires the real call. It is the fastest way to check a payload before writing client code.</p><h2 id="two-playgrounds-one-per-surface" tabindex="-1">Two playgrounds, one per surface <a class="header-anchor" href="#two-playgrounds-one-per-surface" aria-label="Permalink to &quot;Two playgrounds, one per surface&quot;">​</a></h2><p>The shop and admin APIs are documented separately, because they authenticate differently and share no endpoints.</p><table tabindex="0"><thead><tr><th>Playground</th><th>URL</th><th>Endpoints</th></tr></thead><tbody><tr><td>Shop</td><td><code>https://your-domain.com/api/shop</code></td><td>162 operations — catalog, cart, checkout, customer account</td></tr><tr><td>Admin</td><td><code>https://your-domain.com/api/admin</code></td><td>329 operations — orders, catalog management, customers, settings</td></tr></tbody></table><p><code>https://your-domain.com/api</code> lists both and links to each.</p><h2 id="authenticating" tabindex="-1">Authenticating <a class="header-anchor" href="#authenticating" aria-label="Permalink to &quot;Authenticating&quot;">​</a></h2><p>The two surfaces need different credentials, and Swagger UI surfaces them in different places — this is the part that trips people up.</p><h3 id="shop-—-the-storefront-key-is-a-per-operation-field" tabindex="-1">Shop — the storefront key is a per-operation field <a class="header-anchor" href="#shop-—-the-storefront-key-is-a-per-operation-field" aria-label="Permalink to &quot;Shop — the storefront key is a per-operation field&quot;">​</a></h3><p>Every shop operation declares <code>X-STOREFRONT-KEY</code> as a <strong>header parameter</strong>, so it appears as an editable field in that operation&#39;s <strong>Try it out</strong> form. It is not in the <strong>Authorize</strong> dialog, which offers only the Bearer token.</p><p>If the store sets <code>API_PLAYGROUND_AUTO_INJECT_STOREFRONT_KEY=true</code>, the page injects its configured key into every request and you can ignore the field — the banner at the top of the page tells you which mode you are in. With auto-inject off, paste your key into the <code>X-STOREFRONT-KEY</code> field on each operation you try, or requests come back <code>401 missing_key</code>.</p><p>For customer-scoped endpoints, add the Bearer through <strong>Authorize</strong>: the <code>token</code> from login, or a cart token to act as a guest.</p><p>Note that the shop page only persists what you entered across reloads when auto-inject is on. Otherwise a refresh clears it.</p><h3 id="admin-—-bearer-only" tabindex="-1">Admin — Bearer only <a class="header-anchor" href="#admin-—-bearer-only" aria-label="Permalink to &quot;Admin — Bearer only&quot;">​</a></h3><p>Admin operations take no storefront key at all. Click <strong>Authorize</strong>, paste the Integration token in <code>&lt;id&gt;|&lt;token&gt;</code> form, and it applies to every request. The admin page <strong>persists</strong> authorization, so the token survives a reload.</p><h2 id="trying-a-request" tabindex="-1">Trying a request <a class="header-anchor" href="#trying-a-request" aria-label="Permalink to &quot;Trying a request&quot;">​</a></h2><ol><li>Open the surface you need and use the <strong>filter</strong> box at the top to find an endpoint by path or tag.</li><li>Expand the operation — parameters, request body schema, and every documented response are listed.</li><li>Click <strong>Try it out</strong>, fill the fields, and <strong>Execute</strong>.</li><li>Swagger shows the response body, status, headers, and the equivalent <strong>curl</strong> command, which is the quickest way to move a working call into a terminal or a script.</li></ol><p>The server selector at the top is preset to the surface you opened (<code>/api/shop</code> or <code>/api/admin</code>); leave it alone unless you are pointing at a different host.</p><h2 id="the-raw-openapi-spec" tabindex="-1">The raw OpenAPI spec <a class="header-anchor" href="#the-raw-openapi-spec" aria-label="Permalink to &quot;The raw OpenAPI spec&quot;">​</a></h2><p>Each surface publishes its own machine-readable spec:</p><table tabindex="0"><thead><tr><th>Surface</th><th>Spec URL</th></tr></thead><tbody><tr><td>Shop</td><td><code>https://your-domain.com/api/shop/docs</code></td></tr><tr><td>Admin</td><td><code>https://your-domain.com/api/admin/docs</code></td></tr></tbody></table><p>Import either into Postman, Insomnia, or a client generator to get a full request collection without hand-writing anything. Both are plain OpenAPI 3 JSON.</p><p>To generate the same files offline — no running server needed — use the export command, which also writes the GraphQL SDL:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bagisto-api-platform:export-schema</span></span></code></pre></div><h2 id="reading-errors" tabindex="-1">Reading errors <a class="header-anchor" href="#reading-errors" aria-label="Permalink to &quot;Reading errors&quot;">​</a></h2><p>REST signals failure with the status code, and Swagger UI shows it alongside the body.</p><table tabindex="0"><thead><tr><th>Status</th><th>Body</th><th>What it means</th></tr></thead><tbody><tr><td><code>401</code></td><td><code>{&quot;error&quot;: &quot;missing_key&quot;}</code></td><td>No <code>X-STOREFRONT-KEY</code> — fill the field or enable auto-inject</td></tr><tr><td><code>401</code></td><td><code>Invalid or expired token</code></td><td>The Bearer in <strong>Authorize</strong> is wrong, expired, or is the legacy <code>apiToken</code></td></tr><tr><td><code>403</code></td><td><code>{&quot;error&quot;: &quot;invalid_key&quot;}</code></td><td>The storefront key is unknown, deactivated, or expired</td></tr><tr><td><code>403</code></td><td>Problem-details body</td><td>Authenticated, but not allowed — an admin token missing the permission, or a customer&#39;s record that is not theirs</td></tr><tr><td><code>422</code></td><td>Validation details</td><td>The request reached the endpoint and was rejected — read the field errors</td></tr><tr><td><code>429</code></td><td><code>{&quot;error&quot;: &quot;rate_limit_exceeded&quot;}</code></td><td>Rate limit hit; <code>retry_after</code> is in seconds. See <a href="/api/rate-limiting.html">Rate Limiting</a></td></tr></tbody></table><p>A <code>401</code> that says <code>missing_key</code> is about the storefront key; one that mentions a token is about the Bearer. They are separate credentials, and shop endpoints often need both.</p><h2 id="getting-more-from-the-page" tabindex="-1">Getting more from the page <a class="header-anchor" href="#getting-more-from-the-page" aria-label="Permalink to &quot;Getting more from the page&quot;">​</a></h2><ul><li><strong>Filter by tag, not just path.</strong> Endpoints are grouped the way the admin panel is (<code>Admin Sales: Orders</code>, <code>Admin Catalog: Products</code>), so filtering by menu name finds a whole feature at once.</li><li><strong>Read the response schema before the example.</strong> Examples show one shape; the schema lists every field the endpoint can return, including the ones that are null in the sample.</li><li><strong>Copy the curl, not the URL.</strong> The generated curl carries the headers you configured, which is what makes it reproducible outside the browser.</li><li><strong>Watch the paging headers.</strong> Collection responses carry <code>X-Total-Count</code>, <code>X-Page</code>, <code>X-Per-Page</code>, and <code>X-Total-Pages</code>; Swagger shows them under the response body. See <a href="/api/pagination.html">Pagination</a>.</li></ul><h2 id="prefer-graphql" tabindex="-1">Prefer GraphQL? <a class="header-anchor" href="#prefer-graphql" aria-label="Permalink to &quot;Prefer GraphQL?&quot;">​</a></h2><p>The same store serves a GraphQL schema with its own in-browser editor — see the <a href="/api/graphql-api/playground.html">GraphQL Playground Guide</a>.</p><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="/api/rest-api/authentication.html">Authentication</a> — the credential model</li><li><a href="/api/integrations.html">Integration Guides</a> — client code once the request works</li><li><a href="/api/errors.html">Status Codes</a> — the full status and error-body reference</li><li><a href="/api/pagination.html">Pagination</a> — page, per_page, and the response headers</li></ul>',34)]))}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
